$cfg=require __DIR__.'/config.php'; session_name($cfg['session_name']); session_set_cookie_params(['path'=>'/cloud','httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax']); session_start(); if(!empty($_SESSION['cloud_auth'])){header('Location: /cloud/');exit;} header('X-Robots-Tag: noindex, nofollow, noarchive');
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cloud · Вход</title><link rel="stylesheet" href="/cloud/assets/cloud.css?v=2"></head><body class="cloud-login"><main class="login-card"><div class="cloud-logo"><span>◈</span><b>Private Cloud</b></div><p class="kicker">Personal storage</p><h1>Ваше пространство</h1><p class="muted">Войдите, чтобы открыть файлы.</p><form id="login-form"><label>Пароль<input type="password" name="password" autocomplete="current-password" required autofocus></label><button class="primary" type="submit">Войти <span>↗</span></button><p id="login-error" class="error"></p></form></main><script>const form=document.getElementById('login-form'),error=document.getElementById('login-error');form.addEventListener('submit',async event=>{event.preventDefault();error.textContent='';const button=form.querySelector('button');button.disabled=true;try{const response=await fetch('/cloud/api.php?action=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:new FormData(form).get('password')})});const data=await response.json();if(!response.ok)throw Error(data.error||'Не удалось войти');location.href='/cloud/';}catch(errorValue){error.textContent=errorValue.message;button.disabled=false;}});</script></body></html>
